import json,os
G={} # will reload via loader
import os,re
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
def load():
    G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
def split(g):
    w=len(g[0]); mid=g[0].index(5)
    left=[row[:mid] for row in g]; right=[row[mid+1:] for row in g]
    return left,right
def transform(g):
    left,right=split(g)
    out=[]
    for r in range(len(g)):
        row=[]
        for c in range(len(left[0])):
            if left[r][c]!=0: row.append(1)
            else: row.append(2 if right[r][c]!=0 else 0)
        out.append(row)
    return out
# demo1: no overlaps -> union; demo2: overlaps -> left only
def transform2(g):
    left,right=split(g)
    overlap=any(left[r][c]!=0 and right[r][c]!=0 for r in range(len(g)) for c in range(len(left[0])))
    return [[left[r][c] or (2 if (right[r][c] and not overlap) else 0) for c in range(len(left[0]))] for r in range(len(g))]
print(transform(G['Demo pair 1 input']), G['Demo pair 1 output'])
print(transform2(G['Demo pair 1 input']))
print(transform2(G['Demo pair 2 input']), G['Demo pair 2 output'])
